import os
from pathlib import Path

from mcp.server import Server
from mcp.server.stdio import stdio_server
import mcp.types as types

PRIME_HOME_CANDIDATES = [
    Path("/mnt/e/CLAUDE"),
    Path("/e/CLAUDE"),
    Path("E:/CLAUDE"),
]

def detect_prime_home() -> Path:
    for c in PRIME_HOME_CANDIDATES:
        try:
            if c.exists() and c.is_dir():
                return c.resolve()
        except OSError:
            continue
    raise RuntimeError("PRIME_HOME nedetectat (lipsesc /mnt/e/CLAUDE, /e/CLAUDE, E:/CLAUDE)")

PRIME_HOME = detect_prime_home()

def resolve_safe(rel_or_abs: str) -> Path:
    p = Path(rel_or_abs)
    if not p.is_absolute():
        p = PRIME_HOME / p
    p = p.resolve()
    try:
        p.relative_to(PRIME_HOME)
    except ValueError:
        raise PermissionError(f"Path în afara PRIME_HOME: {p}")
    return p

